"""Build a standalone synthetic campaign comparison through the real backend.

Run from the repository or extracted package: python scripts/build_demo_fallback.py
Only docs/demo/fallback.html and comparison.synthetic.{md,json} are written.
All database state is temporary. No sources, models, or research outputs are used.
"""
from __future__ import annotations

import hashlib
import html
import json
from pathlib import Path
import sys
import tempfile

ROOT = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(ROOT))
from reviewdesk.server import ReviewStore, render_campaign_markdown

ANALYST = "SCRIPTED DEMO ANALYST — no human validation"
NOTICE = (
    "Entirely fictional demonstration generated by a script. All campaigns, people, "
    "sources, decisions, category assignments and reported outcomes are synthetic. "
    "No human validation, social reach, causal effect, national impact or real case "
    "status is represented."
)


def make_comparison():
    seed = ROOT / "reviewdesk/demo.synthetic.json"
    document = json.loads(seed.read_text(encoding="utf-8"))
    if document["dataset"]["kind"] != "synthetic" or any(
        item["material_type"] != "synthetic" for item in document["candidates"]
    ):
        raise ValueError("Offline fallback requires synthetic campaign fixtures.")
    with tempfile.TemporaryDirectory(prefix="trialwatch-campaign-fallback-") as temporary:
        store = ReviewStore(seed, Path(temporary) / "state")
        for candidate in document["candidates"]:
            cid = candidate["id"]
            presets = candidate["demo_analysis"]
            review = store.review(cid, {
                "expected_revision": 0, "reviewer": ANALYST, "decision": "include",
                "reason": "Scripted fixture: retain the selected fictional statements for a campaign comparison. This save is not a human validation or factual certification.",
                "duplicate_of": None, "corrections": [],
                "included_claim_ids": [claim["id"] for claim in candidate["claims"]],
            })
            store.campaign(cid, {
                "expected_revision": 0, "expected_review_revision": review["revision"],
                "analyst": ANALYST, "campaign_label": candidate["title"],
                "objective": presets["objective"], "interpretation": presets["interpretation"],
                "alternative_explanations": presets["alternative_explanations"],
                "limitations": presets["limitations"],
                "codings": [{"claim_id": claim["id"], "category": claim["demo_category"]}
                            for claim in candidate["claims"]],
            })
        comparison = store.campaign_export()
        comparison["demo_build"] = {
            "notice": NOTICE, "generator": "scripts/build_demo_fallback.py",
            "seed": "reviewdesk/demo.synthetic.json",
            "seed_sha256": hashlib.sha256(seed.read_bytes()).hexdigest(),
            "workflow": "ReviewStore.review → ReviewStore.campaign → ReviewStore.campaign_export",
            "state": "Temporary synthetic SQLite state; no runtime database included.",
            "coding_origin": "Explicit demo_category and demo_analysis fixture presets; no model inference or human coding session.",
        }
        return comparison


def esc(value):
    return html.escape(str(value), quote=True)


def entries(item, category):
    timeline = item["timelines"][category]
    return timeline["dated"] + timeline["undated"]


def render_html(comparison):
    campaigns = comparison["campaigns"]
    category_labels = comparison["category_labels"]
    heading_cells = "".join(f'<th scope="col">{esc(item["campaign_label"])}</th>' for item in campaigns)
    table_rows = ""
    for category, label in category_labels.items():
        cells = ""
        for item in campaigns:
            count = item["category_summary"][category]["count"]
            content = f'<strong>{count}</strong> coded statement' + ("s" if count != 1 else "") if count else '<span class="unknown">Not documented</span>'
            cells += f"<td>{content}</td>"
        table_rows += f'<tr><th scope="row">{esc(label)}</th>{cells}</tr>'
    case_outcomes = ""
    policy_outcomes = ""
    for item in campaigns:
        for category in ("legal_outcome", "policy_outcome"):
            rows = entries(item, category)
            text = " ".join(claim["text"] for claim in rows) if rows else "Unknown — no outcome evidence selected. This does not establish that no outcome occurred."
            cell = f'<td class="outcome-cell">{esc(text)}</td>'
            if category == "legal_outcome": case_outcomes += cell
            else: policy_outcomes += cell
    table_rows += '<tr class="outcome-row"><th scope="row">What the source reports: case outcome</th>' + case_outcomes + '</tr>'
    table_rows += '<tr class="outcome-row"><th scope="row">Policy development and its limits</th>' + policy_outcomes + '</tr>'

    analyst_cards = ""
    dossiers = ""
    for index, item in enumerate(campaigns, 1):
        analysis = item["analysis"]
        evidence = analysis["evidence_snapshot"]
        analyst_cards += f'''<article class="analysis-card"><span class="eyebrow">Dossier {index:02d} · analyst interpretation</span><h3>{esc(item["campaign_label"])}</h3>
          <div class="label">Objective</div><p>{esc(analysis["objective"])}</p>
          <div class="label">What this record allows us to say</div><p>{esc(analysis["interpretation"])}</p>
          <div class="alternatives"><div class="label">Alternative explanations</div><p>{esc(analysis["alternative_explanations"])}</p></div>
          <div class="label">Limits of this comparison</div><p>{esc(analysis["limitations"])}</p><a href="#dossier-{index}">Inspect the source trail ↓</a></article>'''
        claims = [claim for category in category_labels for claim in entries(item, category)]
        claims.sort(key=lambda claim: (claim["event_date"] is None, claim["event_date"] or "", claim["id"]))
        timeline_html = ""
        for claim in claims:
            source = claim["source"]
            timeline_html += f'''<article class="statement"><div class="statement-head"><strong>{esc(claim["event_date"] or "Event date unknown")}</strong><span class="pill">{esc(category_labels[claim["category"]])}</span></div>
              <h4>{esc(claim["text"])}</h4><p class="small muted">{esc(claim["date_note"])}</p><blockquote>{esc(claim["excerpt"])}</blockquote>
              <p class="source-line">{esc(claim["attribution"])} · {esc(claim["locator"])}</p>
              <p class="source-line">Source: {esc(source["title"])} · Publisher: {esc(source["publisher"])}</p>
              <p class="source-line">Publication: {esc(source["publication_date"] or "unknown")} · Retrieval: {esc(source["retrieved_at"] or "not recorded; synthetic fixture")}</p>
              <p class="url">{esc(source["url"])}</p><p class="small muted">{esc(source["access_note"])} {esc(source["lineage_note"])}</p>
              <p class="small muted">Language: {esc(source["language"])} · {esc(source["translation_status"])}</p>
              <p class="small muted">{esc(claim["verification"])} {esc(claim["classification"])}</p></article>'''
        gaps = "".join(f'<li>{esc(text)}</li>' for text in evidence["unknowns"])
        dates = item["known_event_range"]
        date_text = f'{dates["start"]} to {dates["end"]}' if dates else "No known event dates"
        dossiers += f'''<details class="dossier" id="dossier-{index}"><summary><span><span class="eyebrow">Dossier {index:02d}</span>{esc(item["campaign_label"])}</span><span class="summary-count">{item["coded_observation_count"]} selected statements · expand source trail</span></summary>
          <div class="dossier-body"><div class="dossier-meta"><p><strong>Known selected event range:</strong> {esc(date_text)} · <strong>Unknown event dates:</strong> {item["unknown_event_dates"]}</p><p>Range covers dated selected statements; it is not campaign duration. Source publication dates do not fill missing event dates.</p></div>
          <div class="gaps"><h4>Unresolved evidence gaps</h4><ul>{gaps}</ul></div>{timeline_html}
          <div class="provenance"><p><strong>Analysis revision {analysis["revision"]} · Evidence review revision {analysis["review_revision"]} · Current review revision {item["current_review_revision"]}</strong></p><p>Evidence changed since analysis: {str(item["stale_review"]).lower()} · Current review decision: {esc(item["current_review_decision"])}</p>
          <p>Analyst: {esc(analysis["analyst"])} · Saved: {esc(analysis["saved_at"])}</p><p>{esc(analysis["coding_method"])}</p><p>Evidence snapshot as of: {esc(item["as_of"] or "unknown")} · Present case status remains unverified.</p></div></div></details>'''

    limits = "".join(f"<li>{esc(item)}</li>" for item in comparison["limitations"])
    summary = comparison["summary"]
    return '''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1">
<meta http-equiv="Content-Security-Policy" content="default-src 'none'; style-src 'unsafe-inline'; base-uri 'none'; form-action 'none'">
<title>TrialWatch Campaign Desk · Offline synthetic comparison</title><style>
:root{--ink:#183a3c;--muted:#526765;--paper:#f7f5ee;--line:#d6ded6;--teal:#236c65;--mint:#e1eee5;--gold:#e7bd57;--white:#fff;--warning:#fcf0c9}*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:var(--paper);color:var(--ink);font:16px/1.6 system-ui,-apple-system,"Segoe UI",sans-serif}a{color:var(--teal);text-underline-offset:3px}a:focus-visible,summary:focus-visible{outline:3px solid var(--gold);outline-offset:5px}.synthetic-banner{background:var(--warning);padding:11px 24px;text-align:center;font-size:13px;font-weight:650;letter-spacing:.02em}.shell{max-width:1300px;margin:auto;padding:0 32px}.masthead{display:flex;justify-content:space-between;align-items:center;padding:24px 0;gap:15px}.brand{font-size:19px;font-weight:750;letter-spacing:-.04em}.mode{font-size:12px;text-transform:uppercase;letter-spacing:.12em;color:var(--muted)}.hero{background:var(--ink);color:white;padding:38px 40px 35px;border-radius:18px}.eyebrow{display:block;font-size:11px;letter-spacing:.1em;font-weight:750;text-transform:uppercase}.hero .eyebrow{color:#b9d9cc}.hero h1{font-family:Georgia,serif;font-size:clamp(32px,4vw,47px);line-height:1.13;font-weight:500;max-width:850px;margin:14px 0 17px;letter-spacing:-.025em}.hero p{color:#d8e9df;max-width:860px;margin:0}.hero-meta{margin-top:24px;font-size:13px;display:flex;flex-wrap:wrap;gap:10px 22px;color:#d8e9df}.nav{display:flex;flex-wrap:wrap;gap:10px;padding:20px 0 28px}.nav a{padding:7px 13px;border:1px solid var(--line);border-radius:30px;text-decoration:none;font-size:13px;background:white}main{padding-bottom:35px}section{scroll-margin-top:20px}.section-heading{display:flex;align-items:baseline;justify-content:space-between;gap:12px;margin:22px 0 15px}.section-heading h2{font-family:Georgia,serif;font-size:28px;font-weight:500;margin:0;letter-spacing:-.015em}.section-heading span{font-size:12px;color:var(--muted)}.intro{font-size:14px;color:var(--muted);margin:0 0 18px}.table-wrap{overflow-x:auto;border:1px solid var(--line);border-radius:12px;background:white}table{border-collapse:collapse;width:100%;min-width:840px;font-size:13px;text-align:left}th,td{padding:17px 19px;border-bottom:1px solid var(--line);vertical-align:top}thead th{background:var(--ink);color:white;font-size:14px;line-height:1.4;width:25%}thead th:first-child{width:21%}tbody th{font-size:12px;letter-spacing:.02em;background:#f1f5ef;font-weight:650}td strong{font-size:19px;color:var(--teal);padding-right:4px}.unknown{color:var(--muted);font-style:italic}.outcome-row td{background:#f6f7f1;font-size:13px}.outcome-row th{background:#e9efe4}.outcome-cell{line-height:1.55}tbody tr:last-child th,tbody tr:last-child td{border-bottom:0}.notice{border-left:3px solid var(--gold);padding:13px 17px;background:#fff9e8;font-size:14px;margin:18px 0 24px}.notice p{margin:0}.download-row{display:flex;gap:12px;flex-wrap:wrap;margin:20px 0 0}.download-row a{font-size:14px;font-weight:650;text-decoration:none;border:1px solid var(--teal);padding:9px 16px;border-radius:6px}.download-row a:first-child{background:var(--teal);color:white}.inline-note{font-size:13px;color:var(--muted);margin:14px 0 28px}.analysis-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:20px}.analysis-card{padding:24px;background:white;border:1px solid var(--line);border-radius:12px;border-top:4px solid var(--teal)}.analysis-card .eyebrow{color:var(--muted);font-size:10px}.analysis-card h3{font:500 24px/1.25 Georgia,serif;margin:14px 0 22px}.label{font-size:11px;font-weight:750;text-transform:uppercase;letter-spacing:.06em;color:var(--muted)}.analysis-card p{font-size:13px;margin:6px 0 18px}.analysis-card a{font-size:12px;font-weight:650}.alternatives{background:#f6f0df;margin:0 -11px 18px;padding:14px 11px;border-radius:6px}.alternatives p{margin-bottom:0}.dossier{background:white;border:1px solid var(--line);border-radius:10px;margin:15px 0;scroll-margin-top:18px}.dossier>summary{padding:22px 25px;cursor:pointer;display:flex;justify-content:space-between;gap:15px;align-items:center;font-size:18px;font-weight:650}.dossier>summary .eyebrow{color:var(--muted);font-size:10px;margin-bottom:4px}.summary-count{font-size:12px;color:var(--teal);font-weight:500;text-align:right}.dossier[open]>summary{border-bottom:1px solid var(--line)}.dossier-body{padding:25px}.dossier-meta{font-size:12px;color:var(--muted)}.gaps{background:#f3efe1;padding:15px 20px;border-radius:8px;margin:20px 0}.gaps h4{margin:0;font-size:14px}.gaps ul{font-size:13px;margin-bottom:0;padding-left:20px}.gaps li{margin:8px 0}.statement{padding:20px 0;border-top:1px solid var(--line)}.statement-head{display:flex;justify-content:space-between;flex-wrap:wrap;gap:12px;align-items:center;font-size:13px}.pill{font-size:10px;letter-spacing:.03em;text-transform:uppercase;background:var(--mint);border-radius:20px;padding:4px 10px;color:var(--ink)}h4{font-size:16px;line-height:1.5;margin:13px 0 8px}blockquote{margin:12px 0;padding:11px 15px;border-left:3px solid #83ada0;background:#f1f6f2;font-size:14px}.source-line{font-size:12px;color:var(--muted);margin:5px 0}.small{font-size:12px}.muted{color:var(--muted)}.url{font:12px/1.6 ui-monospace,Consolas,monospace;overflow-wrap:anywhere;color:var(--muted)}.provenance{background:#e6ede7;border-radius:10px;padding:20px;margin-top:20px}.provenance p{font-size:12px;margin:7px 0}.hash{font-family:ui-monospace,Consolas,monospace;overflow-wrap:anywhere}.limits{background:#eceee5;border-radius:12px;padding:24px 30px}.limits ul{font-size:13px;padding-left:18px}.limits li{margin:10px 0}footer{border-top:1px solid var(--line);padding:25px 0 40px;font-size:12px;color:var(--muted)}footer p{margin:6px 0}
@media(max-width:900px){.analysis-grid{grid-template-columns:1fr}.analysis-card h3{font-size:23px}.analysis-card{padding:24px}.alternatives{margin-right:0;margin-left:0}.shell{padding:0 20px}.hero{padding:28px}.section-heading{display:block}.section-heading span{display:block;margin-top:5px}.dossier>summary{align-items:flex-start}.summary-count{max-width:130px}.dossier-body{padding:18px}}@media(max-width:520px){.masthead{align-items:flex-start}.mode{font-size:10px;text-align:right;max-width:105px}.synthetic-banner{font-size:11px}.dossier>summary{display:block}.summary-count{display:block;max-width:none;text-align:left;margin-top:8px}.download-row a{font-size:12px}.shell{padding:0 14px}.hero{padding:24px}}
@media print{body{background:white;font-size:11px}.shell{max-width:none;padding:0}.synthetic-banner{font-size:10px;padding:5px}.masthead{padding:14px 0}.hero{background:white;color:var(--ink);border:1px solid var(--line);padding:18px}.hero h1{font-size:28px}.hero p,.hero .eyebrow,.hero-meta{color:var(--ink)}.nav,.download-row{display:none}.table-wrap{overflow:visible}table{min-width:0;font-size:10px}th,td{padding:8px}.outcome-row td{font-size:10px}.analysis-grid{gap:12px}.analysis-card{padding:14px}.analysis-card p{font-size:10px}.analysis-card h3{font-size:18px}.section-heading h2{font-size:22px}.dossier>summary{font-size:13px}.provenance{padding:12px}footer{padding-bottom:0}}
</style></head><body><div class="synthetic-banner">FICTIONAL DEMONSTRATION · Scripted analyst records · No human validation or measured advocacy impact</div><div class="shell"><header class="masthead"><div class="brand">TrialWatch Campaign Desk</div><div class="mode">Track 3 · Offline fallback</div></header>
<div class="hero"><span class="eyebrow">Campaign evidence → Analyst coding → Cited comparison</span><h1>Campaigns, attention and reported outcomes.</h1><p>Compare what is documented across three fictional Philippines dossiers. Keep source evidence, interpretation and alternative explanations visible as you assess what the record can support.</p>
''' + f'''<div class="hero-meta"><span>{summary["campaign_dossiers"]} synthetic dossiers</span><span>{summary["coded_observations"]} selected coded statements</span><span>{summary["unique_cited_sources"]} distinct cited URLs</span><span>No effectiveness ranking</span></div></div>
<nav class="nav" aria-label="Comparison sections"><a href="#comparison">Compare dossiers</a><a href="#interpretation">Interpretation &amp; alternatives</a><a href="#evidence">Cited evidence</a><a href="#limits">Limits &amp; provenance</a></nav><main>
<section id="comparison"><div class="section-heading"><h2>What is documented?</h2><span>Counts of selected statements · Missing evidence stays unknown</span></div><p class="intro">Two dossiers contain reported legal outcomes. A third contains a draft policy consultation, with case outcome evidence missing. These differences describe the selected record; they cannot establish campaign effectiveness or national impact.</p>
<div class="table-wrap" tabindex="0" role="region" aria-label="Campaign evidence comparison table; scroll horizontally on narrow screens"><table><thead><tr><th scope="col">Evidence category</th>{heading_cells}</tr></thead><tbody>{table_rows}</tbody></table></div>
<div class="notice"><p><strong>Read counts carefully.</strong> A coded statement is not a post, impression, person reached or unit of impact. “Not documented” means no selected evidence in that category, not that activity or an outcome was absent. An adopted policy is distinct from a draft consultation.</p></div>
<div class="download-row"><a href="comparison.synthetic.md" download>Editable comparison memo ↗</a><a href="comparison.synthetic.json" download>Structured evidence + provenance ↗</a></div><p class="inline-note">Saved output generated through the same backend as the app. This page is static; open the app to select evidence, code categories and save a new comparison.</p></section>
<section id="interpretation"><div class="section-heading"><h2>What can we infer?</h2><span>Scripted analyst judgments · No causal claim</span></div><div class="analysis-grid">{analyst_cards}</div></section>
<section id="evidence"><div class="section-heading"><h2>Inspect the source trail</h2><span>Expand a dossier for excerpts, date roles and evidence version</span></div><p class="intro">Timelines preserve known and unknown event dates. Publication dates and retrieval records remain separate. Fictional URLs are displayed for provenance and are never fetched by this page.</p>{dossiers}</section>
<section id="limits"><div class="section-heading"><h2>Limits and provenance</h2><span>Built for accountable comparison</span></div><div class="limits"><p class="small"><strong>{esc(NOTICE)}</strong></p><ul>{limits}</ul><p class="small">{esc(comparison["counting_method"])}</p><p class="small">{esc(comparison["comparison_scope"])}</p><p class="small">{esc(comparison["snapshot_policy"])}</p></div>
<div class="provenance"><p>Generated: {esc(comparison["exported_at"])} · Analyst: {esc(ANALYST)}</p><p>Generation time records a script operation; it is not source retrieval or human review time.</p><p>Generator: {esc(comparison["demo_build"]["generator"])} · Fixture: {esc(comparison["demo_build"]["seed"])}</p><p>{esc(comparison["demo_build"]["coding_origin"])}</p><p class="hash">Seed SHA-256: {esc(comparison["demo_build"]["seed_sha256"])}</p><p>{esc(comparison["demo_build"]["state"])}</p></div></section></main>
<footer><p>{esc(comparison["disclaimer"])}</p><p>Local demonstration · No external assets, network requests or model calls · Open this HTML file directly in a browser.</p></footer></div></body></html>'''


def main():
    comparison = make_comparison()
    target = ROOT / "docs/demo"
    target.mkdir(parents=True, exist_ok=True)
    (target / "comparison.synthetic.json").write_text(json.dumps(comparison, indent=2, ensure_ascii=False) + "\n", encoding="utf-8")
    notice = "**SCRIPTED SYNTHETIC DEMONSTRATION:** " + NOTICE + "\n\n"
    (target / "comparison.synthetic.md").write_text(notice + render_campaign_markdown(comparison), encoding="utf-8")
    (target / "fallback.html").write_text(render_html(comparison), encoding="utf-8")
    print("Built docs/demo/fallback.html and comparison.synthetic.md/json from the real campaign workflow.")
    print("Synthetic scripted records; temporary database removed; no human validation or causal inference.")


if __name__ == "__main__":
    main()
